rial days<input type="number" name="trial_days" min="0" value="<?=e((string)($editPlan['trialDays']??0))?>"></label><label>PPV discount %<input type="number" name="ppv_discount_percent" min="0" max="100" step="0.01" value="<?=e((string)($editPlan['ppvDiscountPercent']??0))?>"></label><label>Sort order<input type="number" name="sort_order" value="<?=e((string)($editPlan['sortOrder']??100))?>"></label></div><label>Benefits <small>one per line</small><textarea name="benefits" rows="7"><?=e(implode("\n",(array)($editPlan['benefits']??[])))?></textarea></label><label class="toggle-row"><input type="checkbox" name="is_active" <?=!isset($editPlan['isActive'])||!empty($editPlan['isActive'])?'checked':''?>><span><b>Active and publicly visible</b><small>Inactive plans remain available for historical subscriptions.</small></span></label><button class="admin-button primary full">Save Membership Plan</button></form><div class="media-record-list"><?php foreach($plans as $plan):?><article class="media-record-card"><div class="plan-icon">♛</div><div><div class="record-badges"><span><?=!empty($plan['isActive'])?'active':'inactive'?></span><span><?=e(App\Core\MembershipPeriod::label((string)$plan['billingInterval'],(int)$plan['intervalCount']))?></span></div><h3><?=e((string)$plan['name'])?></h3><p><?=e((string)$plan['description'])?></p><small><?=e((string)$plan['currency'])?> <?=e(number_format((float)$plan['price'],2))?> · <?=e((string)($plan['ppvDiscountPercent']??0))?>% PPV discount</small></div><a class="mini-button" href="<?=e(base_url('admin/?page=plans&edit='.rawurlencode((string)$plan['id'])))?>">Edit</a></article><?php endforeach;?><?php if($plans===[]):?><div class="admin-empty"><strong>No plans yet.</strong></div><?php endif;?></div></div>
