<script>document.querySelector('[data-entitlement-type]')?.addEventListener('change',event=>{const type=event.target.value;const select=document.querySelector('[data-entitlement-content]');let first=null;[...select.options].forEach(option=>{const visible=option.dataset.contentType===type;option.hidden=!visible;if(visible&&!first)first=option;});if(first)select.value=first.value;});</script>
